const entree = $input.first().json;
const chatInput = typeof entree.chatInput === 'string' ? entree.chatInput.trim() : '';
const texte = chatInput
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase();
const contient = (...termes) => termes.some((terme) => texte.includes(terme));

let intention = 'conversation';
let route = 3;

if (contient('dernier client', 'derniers clients', 'client recent', 'clients recents', 'derniere fiche', 'dernieres fiches', 'dernier dossier', 'derniers dossiers')) {
  intention = 'clients_recents';
  route = 0;
} else if (contient('document', 'piece', 'preuve', 'manquant', 'a recevoir')) {
  intention = 'documents';
  route = 1;
} else if (contient('tache', 'suivi', 'echeance', 'relance')) {
  intention = 'taches';
  route = 2;
}

return [{ json: { ...entree, chatInput, intention, route } }];

const raw = $input.first().json.resultat;
const data = typeof raw === 'string' ? JSON.parse(raw) : raw;
const intention = $('Détecter intention').item.json.intention;

const ambiguite = () => {
  const choix = Array.isArray(data?.correspondances) ? data.correspondances : [];
  return `Plusieurs clients correspondent :\n${choix.map((c, i) => `${i + 1}. ${c.nom_client} — ${c.code_client}`).join('\n')}\n\nPrécisez le client recherché.`;
};

if (data?.ambigue) {
  return [{ json: { output: ambiguite() } }];
}

if (intention !== 'clients_recents' && !data?.trouve) {
  return [{ json: { output: 'Aucun client correspondant n’a été trouvé.' } }];
}

if (intention === 'clients_recents') {
  const clients = Array.isArray(data?.clients) ? data.clients : [];
  const lignes = clients.map((c, i) => `${i + 1}. ${c.nom_client} — ${c.code_client} — ${c.statut_dossier}`);
  return [{ json: { output: clients.length ? `Voici les ${clients.length} clients les plus récents :\n\n${lignes.join('\n')}` : 'Aucun client récent n’est disponible.' } }];
}

if (intention === 'documents') {
  const documents = Array.isArray(data?.documents) ? data.documents : [];
  const lignes = documents.map((d, i) => `${i + 1}. ${d.document} — ${d.statut}`);
  return [{ json: { output: `Documents de ${data.nom_client} (${data.code_client}) : ${data.nombre_documents_manquants} manquant(s) sur ${data.nombre_documents}.\n\n${lignes.join('\n') || 'Aucun document enregistré.'}` } }];
}

const taches = Array.isArray(data?.taches) ? data.taches : [];
const lignes = taches.map((t, i) => `${i + 1}. ${t.titre} — ${t.statut}${t.date_echeance ? ` — échéance ${t.date_echeance}` : ''}`);
return [{ json: { output: `Tâches de ${data.nom_client} (${data.code_client}) : ${data.nombre_taches_ouvertes} ouverte(s) sur ${data.nombre_taches}.\n\n${lignes.join('\n') || 'Aucune tâche enregistrée.'}` } }];
